<template>
  <v-app :class="{ 'theme-dark': darkMode }">
    <transition name="notice-toast"><div v-if="notice" class="notice-toast" :class="'notice-toast--' + noticeType" :role="noticeType === 'error' ? 'alert' : 'status'" aria-live="polite"><span class="notice-toast__icon"><v-icon small>{{ noticeType === 'error' ? 'mdi-alert-circle-outline' : 'mdi-check-circle-outline' }}</v-icon></span><span class="notice-toast__message">{{ notice }}</span><button type="button" class="notice-toast__close" :aria-label="t('إغلاق الرسالة', 'Dismiss message')" @click="notice = ''"><v-icon small>mdi-close</v-icon></button></div></transition>
    <div class="workspace" :class="{ 'workspace--sidebar-collapsed': sidebarCollapsed }" :dir="locale === 'ar' ? 'rtl' : 'ltr'">
