        <div class="sidebar-label">{{ t('مساحة العمل', 'WORKSPACE') }}</div>
        <nav class="workspace-nav">
          <nuxt-link class="workspace-nav__item" :class="{ 'workspace-nav__item--active': activeScreen === 'dashboard' }" :to="adminRoute('dashboard')" @click.native.prevent="navigate('dashboard')"><v-icon>mdi-view-dashboard-outline</v-icon>{{ t('لوحة صفحات السيرفر', 'Server pages') }}<span class="nav-count">{{ pages.length }}</span></nuxt-link>
          <nuxt-link v-if="selectedPage" class="workspace-nav__item" :class="{ 'workspace-nav__item--active': activeScreen === 'editor' }" :to="adminRoute('editor', selectedPage)" @click.native.prevent="goEditor(selectedPage)"><v-icon>mdi-tune-variant</v-icon>{{ t('إعدادات الصفحة', 'Page settings') }}</nuxt-link>
        </nav>
        <div class="sidebar-bottom"><div class="sidebar-label">{{ t('العميل الحالي', 'CURRENT CUSTOMER') }}</div><div class="sidebar-customer"><span class="customer-avatar">{{ client.name.slice(0, 1) }}</span><span><b>{{ client.name }}</b><small>{{ client.domain }}</small></span></div><div class="storage-note"><i></i>{{ t('تخزين تجريبي محلي', 'Local demo storage') }}</div></div>
      </aside>

      <div class="workspace-main">
        <header class="workspace-header">
          <v-btn class="sidebar-toggle-button" icon small :aria-label="t('تبديل القائمة الجانبية', 'Toggle sidebar')" @click="toggleSidebar"><v-icon>{{ sidebarToggleIcon() }}</v-icon></v-btn>
          <div v-if="activeScreen === 'dashboard'" class="header-search"><v-text-field v-model="searchQuery" solo flat dense hide-details clearable prepend-inner-icon="mdi-magnify" :placeholder="t('ابحث في الصفحات...', 'Search pages...')" /></div>
          <div class="header-actions"><v-btn class="header-icon-button" icon small :aria-label="darkMode ? t('الوضع الفاتح', 'Light mode') : t('الوضع الداكن', 'Dark mode')" @click="toggleTheme"><v-icon>{{ darkMode ? 'mdi-white-balance-sunny' : 'mdi-moon-waning-crescent' }}</v-icon></v-btn><v-btn small text @click="toggleLanguage">{{ locale === 'ar' ? 'English' : 'العربية' }}</v-btn></div>
        </header>

        <main id="dashboard" class="workspace-content">
          <section v-if="activeScreen === 'dashboard'" class="page-heading"><div><div class="eyebrow">{{ t('مساحة إدارة صفحات العملاء', 'CUSTOMER PAGE WORKSPACE') }}</div><h1>{{ t('صفحات السيرفر', 'Server pages') }}</h1><p>{{ t('أدر صفحات الزوار وحالات الموقع للعميل المحدد.', 'Manage visitor pages and site statuses for the selected customer.') }}</p></div><div class="heading-actions"><div class="view-toggle"><v-btn small :outlined="viewMode !== 'grid'" :color="viewMode === 'grid' ? 'primary' : ''" @click="viewMode = 'grid'"><v-icon left small>mdi-view-grid-outline</v-icon>{{ t('بطاقات', 'Cards') }}</v-btn><v-btn small :outlined="viewMode !== 'list'" :color="viewMode === 'list' ? 'primary' : ''" @click="viewMode = 'list'"><v-icon left small>mdi-format-list-bulleted</v-icon>{{ t('قائمة', 'List') }}</v-btn></div><v-btn outlined class="secondary-action" @click="resetClient"><v-icon left small>mdi-backup-restore</v-icon>{{ t('استعادة البيانات', 'Restore data') }}</v-btn><v-btn color="primary" @click="newPage"><v-icon left>mdi-plus</v-icon>{{ t('إضافة صفحة', 'Add page') }}</v-btn></div></section>
          <section v-else class="page-heading page-heading--editor"><div><div class="eyebrow">{{ t('تخصيص صفحات الزوار', 'VISITOR PAGE SETTINGS') }}</div><h1>{{ isCreatingPage ? t('إنشاء صفحة جديدة', 'Create a page') : t('إعدادات الصفحة', 'Page settings') }}</h1><p>{{ isCreatingPage ? t('أدخل بيانات الصفحة الجديدة واحفظها لإضافتها للعميل الحالي.', 'Enter the new page details and save to add it to the current customer.') : t('عدّل محتوى الصفحة وراجع المعاينة قبل الحفظ.', 'Edit the page content and review the preview before saving.') }}</p></div><div class="heading-actions"><v-btn outlined class="secondary-action" @click="navigate('dashboard')"><v-icon left small>{{ locale === 'ar' ? 'mdi-arrow-right' : 'mdi-arrow-left' }}</v-icon>{{ t('العودة للصفحات', 'Back to pages') }}</v-btn></div></section>

          <section v-if="activeScreen === 'editor'" class="editor-page-selector"><div><span class="eyebrow">{{ t('العميل الحالي', 'CURRENT CUSTOMER') }}</span><h2>{{ client.name }} <small>{{ client.domain }}</small></h2><p>{{ t('اختر الصفحة التي تريد تعديلها. اختيار صفحة أخرى لا يغيّر الصفحة الافتراضية.', 'Choose a page to edit. Selecting another page does not change the default page.') }}</p></div><v-select :value="selectedPageId" :items="editorPageOptions" item-text="label" item-value="id" outlined dense hide-details :disabled="loading || saving || !pages.length" :label="t('الصفحة المراد تعديلها', 'Page to edit')" :no-data-text="t('لا توجد صفحات لهذا العميل', 'No pages for this customer')" @change="changeEditorPage"><template v-slot:item="{ item }"><div class="editor-page-option"><span><b>{{ item.label }}</b><small>{{ item.typeLabel }}</small></span><v-chip v-if="item.isIndex" x-small class="index-chip">INDEX · {{ t('الرئيسية', 'Home') }}</v-chip></div></template><template v-slot:selection="{ item }"><span class="editor-page-selection"><b>{{ item.label }}</b><small>{{ item.typeLabel }}<template v-if="item.isIndex"> · INDEX</template></small></span></template></v-select></section>

          <section v-if="activeScreen === 'dashboard'" class="customer-panel"><div class="customer-panel__name"><span class="customer-avatar customer-avatar--large">{{ client.name.slice(0, 1) }}</span><div><small>{{ t('العميل الحالي', 'CURRENT CUSTOMER') }}</small><b>{{ client.name }}</b></div></div><v-select :value="clientId" :items="clients" item-text="name" item-value="id" outlined dense hide-details :label="t('اختيار العميل', 'Select customer')" @change="changeClient" /><div class="domain-display"><v-icon small>mdi-web</v-icon><span><small>{{ t('النطاق', 'DOMAIN') }}</small><b>{{ client.domain }}</b></span></div></section>

          <section v-if="activeScreen === 'dashboard'" class="metric-grid"><article class="metric-card"><span class="metric-icon metric-icon--purple"><v-icon>mdi-web</v-icon></span><div><small>{{ t('إجمالي الصفحات', 'TOTAL PAGES') }}</small><b>{{ pages.length }}</b></div></article><article class="metric-card"><span class="metric-icon metric-icon--green"><v-icon>mdi-check-circle-outline</v-icon></span><div><small>{{ t('مفعّلة', 'ACTIVE') }}</small><b>{{ enabledCount }}</b></div></article><article class="metric-card"><span class="metric-icon metric-icon--slate"><v-icon>mdi-pause-circle-outline</v-icon></span><div><small>{{ t('متوقفة', 'INACTIVE') }}</small><b>{{ inactiveCount }}</b></div></article><article class="metric-card"><span class="metric-icon metric-icon--blue"><v-icon>mdi-home-outline</v-icon></span><div><small>INDEX</small><b>{{ indexPage ? label(indexPage) : '—' }}</b></div></article></section>

          <section v-if="activeScreen === 'dashboard' && viewMode === 'grid'" id="status-cards" class="section-block">
            <div class="section-heading"><div><h2>{{ t('حالات الصفحات', 'Page statuses') }}</h2><p>{{ t('فعّل الحالات التي تريد إتاحتها لهذا العميل.', 'Enable the states you need for this customer.') }}</p><p v-if="!indexPage" class="index-warning">{{ t('لم يتم تحديد صفحة INDEX صالحة. اختر صفحة مفعّلة لتكون الصفحة الافتراضية.', 'No valid INDEX page is selected. Choose an enabled page as the default.') }}</p></div><v-select :value="indexPage && indexPage.id" :items="enabledOptions" item-text="label" item-value="id" outlined dense hide-details class="index-select" :label="t('صفحة INDEX', 'INDEX page')" :disabled="loading || !enabledOptions.length" @change="setIndex" /></div>
            <div v-if="loading" class="loading-state"><v-progress-circular indeterminate color="primary" /></div>
            <div v-else class="status-grid"><article v-for="page in filteredPages" :key="page.id" class="status-card" :class="{ 'status-card--selected': selectedPageId === page.id, 'status-card--disabled': !page.enabled, 'status-card--index': page.isIndex }" @click="goEditor(page)">
              <div class="status-card__top"><span class="status-card__icon" :class="'tone-' + toneFor(page)"><v-icon>{{ iconFor(page) }}</v-icon></span><v-spacer /><button type="button" class="page-toggle" role="switch" :aria-checked="page.enabled ? 'true' : 'false'" :aria-label="t('تفعيل أو تعطيل', 'Toggle status')" @click.stop="togglePage(page, !page.enabled)"><span class="page-toggle__track"><span class="page-toggle__thumb"></span></span></button></div>
              <small class="status-card__code">{{ page.code }}</small><h3>{{ label(page) }}</h3><div class="card-preview"><VisitorPage :page="page" :domain="client.domain" :locale="locale" /></div><p>{{ localized(page, 'message') }}</p><div class="status-card__footer"><span class="state-label" :class="page.enabled ? 'state-enabled' : 'state-disabled'"><i></i>{{ page.enabled ? t('مفعّلة', 'Enabled') : t('متوقفة', 'Disabled') }}</span><div class="card-actions"><v-btn text x-small @click.stop="openVisitor(page)"><v-icon left x-small>mdi-open-in-new</v-icon>{{ t('معاينة', 'Preview') }}</v-btn><v-btn text x-small @click.stop="goEditor(page)">{{ t('تعديل', 'Edit') }}<v-icon right x-small>mdi-pencil-outline</v-icon></v-btn></div></div>
            </article></div>
          </section>

          <section v-if="activeScreen === 'dashboard' && viewMode === 'list'" id="page-table" class="section-block table-section"><div class="section-heading"><div><h2>{{ t('كل الصفحات', 'All pages') }}</h2><p>{{ t('اختر صفحة لعرض إعداداتها أو تنفيذ إجراء.', 'Select a page to edit or run an action.') }}</p></div><div class="list-heading-actions"><v-select :value="indexPage && indexPage.id" :items="enabledOptions" item-text="label" item-value="id" outlined dense hide-details :label="t('صفحة INDEX', 'INDEX page')" :disabled="loading || !enabledOptions.length" @change="setIndex" /><span class="table-count">{{ filteredPages.length }} {{ t('صفحات', 'pages') }}</span></div></div>
            <div v-if="!filteredPages.length" class="empty-state"><v-icon>mdi-file-search-outline</v-icon><b>{{ searchQuery ? t('لا توجد نتائج مطابقة', 'No matching pages') : t('لا توجد صفحات', 'No pages') }}</b><span>{{ searchQuery ? t('جرّب عبارة بحث أخرى.', 'Try another search.') : t('أضف صفحة مخصصة للبدء.', 'Add a custom page to get started.') }}</span></div>
            <div v-else class="table-scroll"><table class="pages-table"><thead><tr><th>{{ t('النوع', 'TYPE') }}</th><th>{{ t('العنوان', 'TITLE') }}</th><th>{{ t('الحالة', 'STATUS') }}</th><th>INDEX</th><th>{{ t('الإجراءات', 'ACTIONS') }}</th></tr></thead><tbody>
              <tr v-for="page in filteredPages" :key="page.id" :class="{ 'row-selected': selectedPageId === page.id }" @click="goEditor(page)"><td><span class="table-type"><v-icon small>{{ iconFor(page) }}</v-icon>{{ page.code }}</span></td><td><b>{{ label(page) }}</b><small>{{ page.type.startsWith('custom-') ? t('صفحة مخصصة', 'Custom page') : t('صفحة نظام', 'System page') }}</small></td><td><div class="table-status"><span class="state-label" :class="page.enabled ? 'state-enabled' : 'state-disabled'"><i></i>{{ page.enabled ? t('مفعّلة', 'Enabled') : t('متوقفة', 'Disabled') }}</span><button type="button" class="page-toggle" role="switch" :aria-checked="page.enabled ? 'true' : 'false'" :aria-label="t('تفعيل أو تعطيل', 'Toggle status')" @click.stop="togglePage(page, !page.enabled)"><span class="page-toggle__track"><span class="page-toggle__thumb"></span></span></button></div></td><td><v-chip v-if="page.isIndex" x-small class="index-chip">INDEX</v-chip><span v-else>—</span></td><td><div class="row-actions" @click.stop><v-btn icon x-small :aria-label="t('فتح المعاينة', 'Open preview')" @click="openVisitor(page)"><v-icon small>mdi-open-in-new</v-icon></v-btn><v-btn icon x-small :aria-label="t('تعديل', 'Edit')" @click="goEditor(page)"><v-icon small>mdi-pencil-outline</v-icon></v-btn><v-btn v-if="page.type.startsWith('custom-')" icon x-small color="error" :aria-label="t('حذف', 'Delete')" :disabled="page.isIndex" @click="deleteTarget = page; deleteOpen = true"><v-icon small>mdi-delete-outline</v-icon></v-btn></div></td></tr>
            </tbody></table></div>
          </section>

          <section v-if="activeScreen === 'editor'" id="page-editor" class="section-block"><div class="section-heading"><div><h2>{{ t('محتوى الصفحة', 'Page content') }}</h2><p>{{ t('التعديل يظهر مباشرة في المعاينة قبل الحفظ.', 'Edits appear in the preview before saving.') }}</p></div></div>
            <div v-if="!draft" class="empty-state"><v-icon>mdi-cursor-default-click-outline</v-icon><b>{{ t('اختر صفحة من القائمة أعلاه لبدء التعديل', 'Choose a page from the selector above to start editing') }}</b><span>{{ t('لن يتم اختيار INDEX تلقائيًا عند فتح المحرر دون صفحة محددة.', 'INDEX is not selected automatically when the editor opens without a page.') }}</span></div>
            <div v-else class="editor-layout"><PageEditorForm
              :draft="draft"
              :locale="locale"
              :page-label="label(draft)"
              :icon="iconFor(draft)"
              :tone="toneFor(draft)"
              :is-creating="isCreatingPage"
              :settings-tab="settingsTab"
              :alignments="alignments"
              :saving="saving"
              :has-unsaved-changes="hasUnsavedChanges"
              @update:draft="draft = $event"
              @settings-tab-change="settingsTab = $event"
              @save="savePage"
              @cancel="discardDraft"
              @select-logo="readLogo"
              @select-image="readImage"
            /><aside class="preview-panel"><div class="preview-panel__heading"><span><v-icon small>mdi-eye-outline</v-icon>{{ t('معاينة مباشرة', 'Live preview') }}</span><div class="preview-controls"><v-btn-toggle v-model="previewMode" dense mandatory><v-btn value="desktop" x-small :aria-label="t('معاينة سطح المكتب', 'Desktop preview')"><v-icon small>mdi-monitor</v-icon></v-btn><v-btn value="mobile" x-small :aria-label="t('معاينة الهاتف', 'Mobile preview')"><v-icon small>mdi-cellphone</v-icon></v-btn></v-btn-toggle><v-btn icon x-small :aria-label="t('فتح مستقل', 'Open standalone')" @click="openVisitor(draft)"><v-icon small>mdi-open-in-new</v-icon></v-btn></div></div><div class="preview-frame" :class="'preview-frame--' + previewMode"><VisitorPage :page="draft" :domain="client.domain" :locale="locale" /></div><div class="preview-domain"><v-icon small>mdi-web</v-icon>{{ client.domain }}<span>{{ t('محلي', 'Local') }}</span></div></aside></div>
          </section>

        </main>
      </div>
    </div>
    <v-dialog v-model="deleteOpen" max-width="440"><v-card class="workspace-dialog"><v-card-title>{{ t('حذف الصفحة المخصصة؟', 'Delete custom page?') }}</v-card-title><v-card-text>{{ t('ستُحذف من بيانات العميل المحدد فقط.', 'Only this customer’s record will be deleted.') }} <b>{{ deleteTarget ? label(deleteTarget) : '' }}</b></v-card-text><v-card-actions><v-spacer /><v-btn text @click="deleteOpen = false">{{ t('إلغاء', 'Cancel') }}</v-btn><v-btn color="error" @click="deletePage">{{ t('حذف الصفحة', 'Delete page') }}</v-btn></v-card-actions></v-card></v-dialog>
  </v-app>
</template>
<script>
import VisitorPage from "~/components/VisitorPage.vue";
import PageEditorForm from "~/components/PageEditorForm.vue";
import { DEMO_CLIENTS } from "~/data/templates";
import { pageRepository } from "~/services/pageRepository";
import { isValidActionUrl, isValidHexColor, isValidImageSource } from "~/utils/pageValidation";
const clone = (value) => JSON.parse(JSON.stringify(value));
function createCustomPageDraft(clientId, id) { return { id, type: id, clientId, code: "CUSTOM", enabled: true, isIndex: false, title: "Custom page", titleAr: "صفحة مخصصة", message: "This page is available for your visitors.", messageAr: "هذه الصفحة متاحة لزوار الموقع.", buttonLabel: "", buttonLabelAr: "", buttonUrl: "", design: { background: "#f7f9f8", text: "#1d312e", button: "#315c56", imageUrl: "", logoUrl: "", alignment: "start" } }; }
const THEME_KEY = "server-pages-standalone:theme:v1";
export default {
  components: { VisitorPage, PageEditorForm },
  data() {
    let clientId = DEMO_CLIENTS[0].id; let darkMode = false;
    const routeClientId = this.$route && this.$route.query.clientId;
    if (DEMO_CLIENTS.some((client) => client.id === routeClientId)) clientId = routeClientId;
    return { clients: DEMO_CLIENTS, clientId, pages: [], loading: true, saving: false, loadError: "", locale: this.$route && this.$route.query.lang === "en" ? "en" : "ar", darkMode, mobileMenuOpen: false, sidebarCollapsed: false, searchQuery: "", viewMode: "grid", previewMode: "desktop", settingsTab: 0, selectedPageId: null, draft: null, isCreatingPage: false, deleteOpen: false, deleteTarget: null, notice: "", noticeType: "success", alignments: [{ value: "start", text: "Start" }, { value: "center", text: "Center" }, { value: "end", text: "End" }] };
  },
  computed: {
    client() { return this.clients.find((item) => item.id === this.clientId) || this.clients[0]; },
    selectedPage() { return this.pages.find((page) => page.id === this.selectedPageId) || null; },
    indexPage() { const indexes = this.pages.filter((page) => page.isIndex); return indexes.length === 1 && indexes[0].enabled ? indexes[0] : null; },
    enabledCount() { return this.pages.filter((page) => page.enabled).length; },
    filteredPages() { const q = String(this.searchQuery || "").trim().toLowerCase(); return q ? this.pages.filter((page) => [page.type, page.code, page.title, page.titleAr, page.message, page.messageAr].some((value) => String(value || "").toLowerCase().includes(q))) : this.pages; },
    enabledOptions() { return this.pages.filter((page) => page.enabled).map((page) => ({ id: page.id, label: this.label(page) })); },
    editorPageOptions() { const options = this.pages.map((page) => ({ id: page.id, label: this.label(page), typeLabel: page.code || page.type, isIndex: page.isIndex })); if (this.isCreatingPage && this.draft && !options.some((page) => page.id === this.draft.id)) options.unshift({ id: this.draft.id, label: this.label(this.draft), typeLabel: this.t("غير محفوظة", "Unsaved"), isIndex: false }); return options; },
    activeScreen() { return this.$route.query.screen === "editor" ? "editor" : "dashboard"; },
    inactiveCount() { return this.pages.filter((page) => !page.enabled).length; },
    hasUnsavedChanges() { if (!this.draft) return false; const saved = this.pages.find((page) => page.id === this.draft.id); return !saved || JSON.stringify(saved) !== JSON.stringify(this.draft); },
  },
  created() { if (process.client) this.$vuetify.theme.dark = this.darkMode; },
  mounted() {
    let rememberedClient = null; let rememberedTheme = "light";
    try { rememberedClient = window.localStorage.getItem("server-pages-standalone:v1:selected-client"); rememberedTheme = window.localStorage.getItem(THEME_KEY) || "light"; } catch (error) {}
    if (!this.$route.query.clientId && this.clients.some((client) => client.id === rememberedClient)) {
      this.clientId = rememberedClient;
      this.$router.replace({ path: "/admin", query: { ...this.$route.query, clientId: rememberedClient } }).catch(() => {});
    }
    this.darkMode = rememberedTheme === "dark";
    this.$vuetify.theme.dark = this.darkMode;
    document.documentElement.setAttribute("data-color-scheme", this.darkMode ? "dark" : "light");
  },
  watch: { clientId: { handler() { this.loadPages(); }, immediate: true }, "$route.query.lang"(lang) { this.locale = lang === "en" ? "en" : "ar"; } },
  methods: {
    sidebarToggleIcon() { if (typeof window !== "undefined" && window.matchMedia("(max-width: 1024px)").matches) return this.mobileMenuOpen ? "mdi-close" : "mdi-menu"; return this.sidebarCollapsed ? "mdi-menu" : "mdi-menu-open"; },
    toggleSidebar() { if (window.matchMedia("(max-width: 1024px)").matches) { this.mobileMenuOpen = !this.mobileMenuOpen; return; } this.sidebarCollapsed = !this.sidebarCollapsed; },
    adminRoute(screen, page) { const query = { ...this.$route.query, screen, clientId: this.clientId }; delete query.newPage; if (page) query.pageId = page.id; else delete query.pageId; return { path: "/admin", query }; },
    changeClient(clientId) { if (this.hasUnsavedChanges && !window.confirm(this.t("لديك تعديلات غير محفوظة. هل تريد تبديل العميل؟", "You have unsaved changes. Switch customers?"))) return; if (!this.clients.some((client) => client.id === clientId)) return; this.clientId = clientId; this.selectedPageId = null; this.draft = null; if (this.$router) this.$router.push({ path: "/admin", query: { ...this.$route.query, clientId, screen: this.activeScreen === "editor" ? "dashboard" : this.activeScreen, pageId: undefined } }); },
    navigate(screen, page) { if (this.hasUnsavedChanges && !window.confirm(this.t("لديك تعديلات غير محفوظة. هل تريد المتابعة دون حفظها؟", "You have unsaved changes. Continue without saving?"))) return; if (page) { this.selectedPageId = page.id; this.draft = clone(page); } this.mobileMenuOpen = false; const target = this.adminRoute(screen, page || (screen === "editor" ? this.selectedPage : null)); if (this.$router) this.$router.push(target); },
    changeEditorPage(pageId) { const page = this.pages.find((entry) => entry.id === pageId); if (!page || page.id === this.selectedPageId) return; if (this.hasUnsavedChanges && !window.confirm(this.t("لديك تعديلات غير محفوظة على الصفحة الحالية. هل تريد إلغاءها والانتقال إلى الصفحة المختارة؟", "The current page has unsaved changes. Discard them and switch to the selected page?"))) return; this.selectedPageId = page.id; this.draft = clone(page); this.isCreatingPage = false; if (this.$router) this.$router.push(this.adminRoute("editor", page)); },
    goEditor(page) { return this.navigate("editor", page); },
    t(ar, en) { return this.locale === "ar" ? ar : en; },
    label(page) { return this.locale === "ar" ? (page.titleAr || page.title) : (page.title || page.titleAr); },
    localized(page, field) { return this.locale === "ar" ? (page[field + "Ar"] || page[field]) : (page[field] || page[field + "Ar"]); },
    iconFor(page) { return ({ index: "mdi-home-outline", "404": "mdi-file-question-outline", "403": "mdi-lock-outline", "500": "mdi-server-off", maintenance: "mdi-wrench-outline", "coming-soon": "mdi-rocket-launch-outline", suspended: "mdi-pause-circle-outline" })[page.type] || "mdi-web"; },
    toneFor(page) { return ({ index: "purple", "404": "blue", "403": "orange", "500": "red", maintenance: "amber", "coming-soon": "blue", suspended: "slate" })[page.type] || "purple"; },
    async loadPages() { this.loading = true; this.loadError = ""; try { this.pages = await pageRepository.list(this.clientId); } catch (error) { this.pages = []; this.loadError = error && error.code === "invalid-data" ? this.t("تعذر قراءة إعدادات الصفحات المحفوظة؛ لم يتم استبدالها ببيانات افتراضية.", "Saved page settings are invalid; they were not replaced with defaults.") : this.t("تعذر تحميل إعدادات العميل.", "Could not load customer page settings."); this.notify(this.loadError, "error"); } const query = (this.$route && this.$route.query) || {}; const requestedId = query.pageId; const requested = this.pages.find((page) => page.id === requestedId); const isNewPageRoute = query.newPage === "1" && typeof requestedId === "string" && requestedId.startsWith("custom-" + this.clientId + "-") && !requested && !this.loadError; if (isNewPageRoute) { this.selectedPageId = requestedId; this.draft = this.draft && this.draft.id === requestedId ? clone(this.draft) : createCustomPageDraft(this.clientId, requestedId); this.isCreatingPage = true; } else { const chosen = requested || (this.activeScreen === "editor" ? null : this.pages.find((page) => page.id === this.selectedPageId) || this.indexPage); this.selectedPageId = chosen ? chosen.id : null; this.draft = chosen ? clone(chosen) : null; this.isCreatingPage = false; } this.loading = false; try { window.localStorage.setItem("server-pages-standalone:v1:selected-client", this.clientId); } catch (error) {} },
    async commit(next, message) { if (this.loadError) return false; const before = clone(this.pages); this.saving = true; this.pages = next; let result = null; try { result = await pageRepository.save(this.clientId, next); } catch (error) { result = { ok: false, reason: "unavailable" }; } finally { this.saving = false; } if (!result || result.ok !== true) { this.pages = before; this.notify(result && result.reason === "quota" ? this.t("مساحة التخزين غير كافية. قلّل حجم الصور أو استخدم روابط صور.", "Browser storage is full. Reduce image sizes or use image URLs.") : this.t("تعذر الحفظ؛ لم يتم اعتماد التغييرات.", "Save failed; changes were not applied."), "error"); return false; } if (message) this.notify(message); return true; },
    notify(message, type) { this.notice = message; this.noticeType = type || "success"; },
    selectPage(page) { this.selectedPageId = page.id; this.draft = clone(page); this.isCreatingPage = false; },
    editPage(page) { this.selectPage(page); },
    async discardDraft() { if (this.isCreatingPage || !this.selectedPage) { this.draft = null; this.selectedPageId = null; this.isCreatingPage = false; return this.navigate("dashboard"); } this.draft = clone(this.selectedPage); },
    async setIndex(id) { const candidate = this.pages.find((page) => page.id === id); if (!candidate || !candidate.enabled) { this.notify(this.t("اختر صفحة مفعّلة لتعيينها كصفحة INDEX.", "Choose an enabled page as INDEX."), "error"); return; } const next = clone(this.pages); next.forEach((page) => { page.isIndex = page.id === id; }); if (await this.commit(next, this.t("تم تغيير الصفحة الافتراضية.", "Default page updated."))) { const selected = this.pages.find((page) => page.id === this.selectedPageId); if (selected) this.draft = clone(selected); } },
    async togglePage(page, enabled) { const next = clone(this.pages); const item = next.find((entry) => entry.id === page.id); if (!item) return; item.enabled = enabled === true; if (!next.some((entry) => entry.enabled)) { this.notify(this.t("يجب إبقاء صفحة واحدة مفعّلة على الأقل.", "At least one page must remain enabled."), "error"); return; } if (item.isIndex && !item.enabled) item.isIndex = false; if (await this.commit(next, this.t("تم تحديث الحالة.", "Page status updated.")) && this.selectedPageId === page.id) { const selected = this.pages.find((entry) => entry.id === page.id); if (selected) this.draft = clone(selected); } },
    newPage() { if (this.hasUnsavedChanges && !window.confirm(this.t("لديك تعديلات غير محفوظة. هل تريد بدء صفحة جديدة؟", "You have unsaved changes. Start a new page?"))) return; let id; do { id = "custom-" + this.clientId + "-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10); } while (this.pages.some((page) => page.id === id)); this.draft = createCustomPageDraft(this.clientId, id); this.selectedPageId = id; this.isCreatingPage = true; if (this.$router) { const route = this.adminRoute("editor", this.draft); route.query.newPage = "1"; this.$router.push(route); } },
    async savePage() { if (!this.draft.title.trim() || !this.draft.titleAr.trim() || !this.draft.message.trim() || !this.draft.messageAr.trim()) { this.notify(this.t("أدخل العنوان والرسالة باللغتين.", "Enter a title and message in both languages."), "error"); return; } if (![this.draft.design.background, this.draft.design.text, this.draft.design.button].every(isValidHexColor) || !isValidImageSource(this.draft.design.imageUrl) || !isValidImageSource(this.draft.design.logoUrl) || !isValidActionUrl(this.draft.buttonUrl)) { this.notify(this.t("تحقق من الألوان والروابط.", "Check colors and URLs."), "error"); return; } const next = clone(this.pages); const i = next.findIndex((page) => page.id === this.draft.id); if (i < 0) next.push(clone(this.draft)); else next.splice(i, 1, clone(this.draft)); if (!next.some((page) => page.enabled)) { this.notify(this.t("يجب إبقاء صفحة واحدة مفعّلة على الأقل.", "At least one page must remain enabled."), "error"); return; } if (this.draft.isIndex && !this.draft.enabled) next.forEach((page) => { page.isIndex = false; }); this.selectedPageId = this.draft.id; if (await this.commit(next, this.t("تم حفظ الصفحة.", "Page saved."))) { this.isCreatingPage = false; this.draft = clone(this.pages.find((page) => page.id === this.selectedPageId)); if (this.$router && this.$route.query.newPage) await this.$router.replace(this.adminRoute("editor", this.draft)).catch(() => {}); } },
    async deletePage() { if (!this.deleteTarget || !this.deleteTarget.type.startsWith("custom-") || this.deleteTarget.isIndex) return; const id = this.deleteTarget.id; const next = this.pages.filter((page) => page.id !== id); if (!next.length || !await this.commit(next, this.t("تم حذف الصفحة.", "Page deleted."))) return; if (this.selectedPageId === id) { const replacement = this.pages.find((page) => page.isIndex) || this.pages[0]; this.selectedPageId = replacement ? replacement.id : null; this.draft = replacement ? clone(replacement) : null; } this.deleteOpen = false; this.deleteTarget = null; },
    async resetClient() { if (!await pageRepository.reset(this.clientId)) { this.notify(this.t("تعذر مسح بيانات العميل من التخزين.", "Could not clear this customer's browser storage."), "error"); return; } this.selectedPageId = null; await this.loadPages(); this.notify(this.t("تمت استعادة بيانات العميل المحدد.", "Selected customer's demo data was restored.")); },
    toggleTheme() { this.darkMode = !this.darkMode; this.$vuetify.theme.dark = this.darkMode; document.documentElement.setAttribute("data-color-scheme", this.darkMode ? "dark" : "light"); try { window.localStorage.setItem(THEME_KEY, this.darkMode ? "dark" : "light"); } catch (error) {} },
    openVisitor(page) { if (typeof window !== "undefined") window.open(this.visitorRoute(page), "_blank", "noopener"); },
    async toggleLanguage() { this.locale = this.locale === "ar" ? "en" : "ar"; if (this.$router) await this.$router.replace({ path: "/admin", query: { ...this.$route.query, lang: this.locale } }).catch(() => {}); },
    readImage(file) { if (!file) return; if (!/^image\/(png|jpeg|gif|webp)$/.test(file.type) || file.size > 2 * 1024 * 1024) { this.notify(this.t("اختر صورة مدعومة أقل من 2 ميجابايت.", "Choose a supported image under 2 MB."), "error"); return; } const reader = new FileReader(); reader.onload = () => { if (typeof reader.result === "string") this.draft.design.imageUrl = reader.result; else this.notify(this.t("تعذر تجهيز الصورة.", "Could not process the image."), "error"); }; reader.onerror = () => this.notify(this.t("تعذر قراءة الصورة. لم يتم تغيير إعدادات الصفحة.", "Could not read the image. Page settings were not changed."), "error"); reader.readAsDataURL(file); },
    readLogo(file) { if (!file) return; if (!/^image\/(png|jpeg|gif|webp)$/.test(file.type) || file.size > 2 * 1024 * 1024) { this.notify(this.t("اختر شعارًا مدعومًا أقل من 2 ميجابايت.", "Choose a supported logo under 2 MB."), "error"); return; } const reader = new FileReader(); reader.onload = () => { if (typeof reader.result === "string") this.draft.design.logoUrl = reader.result; else this.notify(this.t("تعذر تجهيز الشعار.", "Could not process the logo."), "error"); }; reader.onerror = () => this.notify(this.t("تعذر قراءة الشعار. لم يتم تغيير إعدادات الصفحة.", "Could not read the logo. Page settings were not changed."), "error"); reader.readAsDataURL(file); },
    visitorRoute(page) { return "/server-pages-preview/" + encodeURIComponent(page.type) + "?clientId=" + encodeURIComponent(this.clientId) + "&pageId=" + encodeURIComponent(page.id) + "&domain=" + encodeURIComponent(this.client.domain) + "&lang=" + this.locale; },
  },
};
</script>

